import re

file_path = "/mnt/c/Users/User/plizio-repo/lib/visualLab/data/belgiumPoi.ts"

with open(file_path, "r", encoding="utf-8") as f:
    content = f.read()

for poi_id, updates in data.items():
    start_match = re.search(rf'id:\s*"{poi_id}"', content)
    if not start_match:
        continue
    
    start_pos = start_match.start()
    block_start = content.rfind('{', 0, start_pos)
    
    brace_count = 0
    block_end = -1
    for i in range(block_start, len(content)):
        if content[i] == '{':
            brace_count += 1
        elif content[i] == '}':
            brace_count -= 1
            if brace_count == 0:
                block_end = i + 1
                break
    
    if block_end == -1:
        continue
        
    block = content[block_start:block_end]
    new_block = block
    
    if "descriptionAdvanced" in updates:
        if "descriptionAdvanced:" in new_block:
            desc_match = re.search(r'descriptionAdvanced:\s*\{([^}]*)\}', new_block, re.DOTALL)
            if desc_match:
                inner_desc = desc_match.group(1)
                hu_match = re.search(r'hu:\s*"([^"]*)"', inner_desc)
                if hu_match and (not hu_match.group(1).strip() or len(hu_match.group(1)) < 50):
                    new_inner = re.sub(r'(hu:\s*")[^"]*(")', r'\1' + updates["descriptionAdvanced"] + r'\2', inner_desc)
                    new_block = new_block.replace(inner_desc, new_inner)
        else:
            insertion_point = -1
            for field in ["facts:", "factsAdvanced:", "image:", "}"]:
                m = re.search(rf'\n\s+{field}', new_block)
                if m:
                    insertion_point = m.start()
                    break
            
            desc_adv_text = f'\n    descriptionAdvanced: {{\n      de: "",\n      hu: "{updates["descriptionAdvanced"]}",\n      ro: "",\n      en: ""\n    }},'
            new_block = new_block[:insertion_point] + desc_adv_text + new_block[insertion_point:]

    if "factsAdvanced" in updates:
        facts_hu_str = '",\n        "'.join(updates["factsAdvanced"])
        facts_hu_str = f'"{facts_hu_str}"'
        
        if "factsAdvanced:" in new_block:
            fa_match = re.search(r'factsAdvanced:\s*\{([^}]*)\}', new_block, re.DOTALL)
            if fa_match:
                inner_fa = fa_match.group(1)
                new_inner_fa = re.sub(r'(hu:\s*\[)[^\]]*(\])', r'\1\n        ' + facts_hu_str + r'\n      \2', inner_fa, flags=re.DOTALL)
                new_block = new_block.replace(inner_fa, new_inner_fa)
        else:
            insertion_point = -1
            for field in ["image:", "}"]:
                m = re.search(rf'\n\s+{field}', new_block)
                if m:
                    insertion_point = m.start()
                    break
            
            facts_adv_text = f'\n    factsAdvanced: {{\n      de: [],\n      hu: [\n        {facts_hu_str}\n      ],\n      ro: [],\n      en: []\n    }},'
            new_block = new_block[:insertion_point] + facts_adv_text + new_block[insertion_point:]

    content = content[:block_start] + new_block + content[block_end:]

with open(file_path, "w", encoding="utf-8") as f:
    f.write(content)
